import json,os,subprocess,pathlib,argparse
parser=argparse.ArgumentParser(description='Create explicit, pinned operations qualification inputs')
for flag in ['runner','tree','bindings','http','prior-report','output','codex']:
 parser.add_argument('--'+flag,required=True)
parser.add_argument('--arc-base',required=True,help='Pinned ArcNexus commit before the reporting improvement')
options=parser.parse_args()
root=str(pathlib.Path(__file__).resolve().parents[2]);dest=str(pathlib.Path(options.output).resolve());os.mkdir(dest,0o700)
def write(name,value):
 p=dest+'/'+name;open(p,'w').write(json.dumps(value,indent=2)+'\n');return p
node='/usr/bin/node';check=root+'/scripts/qualification/check-run.mjs';accept=root+'/scripts/qualification/report-operations.mjs';inject=root+'/scripts/qualification/inject-report-defect.mjs'
base=subprocess.check_output(['git','-C',root,'rev-parse','--verify','--end-of-options',options.arc_base+'^{commit}'],text=True).strip()
criteria=['Markdown has ## Operations with each captured operation id, passed when exitCode=0 otherwise failed, durationMs and log path; ## Managed services with id, status and endpointClosed boolean.','Historical absent/empty arrays show exactly No managed operations recorded. and No managed services recorded.; never undefined/null. Preserve existing sections and do not mutate records.','Document behavior and add regression tests including a built CLI report assertion. Run report-tests through operations.run for actual feedback; update plan checklist with evidence and provide caller handoff.']
objective='Add Operations and Managed services summaries to the Markdown report using only captured JSON fields. Modify only src/report.ts, tests/runtime/report.test.mjs and docs/report.md. Inspect src/operations.ts and src/services.ts read-only for record shape. Preserve existing report fields. During specification edit docs/tests only, invoke operations.run report-tests to observe the regression, and select the captured focused node --test tests/runtime/report.test.mjs command if available, otherwise npm test (use the zero-based verificationIndex) with a distinctive literal assertion diagnostic for the host expected-red check. Implementation may build dist with npm run build before exploratory report-tests. Complete every checklist item or validly skip it with reason, respecting dependency order. No commits; caller owns issue/branch/release steps.'
def assignment(kind,objective,criteria,**kw):return dict(schemaVersion=2,kind=kind,objective=objective,expectedOutcome=objective,acceptanceCriteria=criteria,hostChecks=[],**kw)
a=assignment('change',objective,criteria,allowedWritePaths=['src/report.ts','tests/runtime/report.test.mjs','docs/report.md']);a['hostChecks']=[dict(id='report-operations',command=node,args=[accept],artifacts=[accept])];normal=write('change.json',a)
a['hostChecks']=[dict(id='injected-report-repair',command=node,args=[inject,dest+'/fault-marker.json',accept],artifacts=[inject,accept])];repair=write('repair.json',a)
tree=write('tree.json',assignment('research','Inspect the Platform artifact-diagnostics responsibility and pinned read-only CLI/SDK owners. Invoke operations.run artifact-diagnostics-tests once to obtain real bound-Bun test feedback. Explain what those archive tests establish and remaining uncertainty; do not edit source or start servers. Complete the checklist with observed evidence.', ['Use the declared artifact-diagnostics-tests operation and report real output.','Explain repository ownership and diagnostic behavior from actual files and tests, with evidence and uncertainty.']))
http=write('http.json',assignment('research','Qualify the declared local HTTP service without source edits. During execution use services.start serve, operations.run health, services.logs serve and services.stop serve; report readiness, response, logs and closed endpoint. Complete the checklist with evidence. Planning should only plan, not start the service.', ['Demonstrate managed local service readiness, declared HTTP request and bounded log access.','Stop the service and report its lifecycle evidence without source edits.']))
prior=dest+'/prior-findings.txt';r=json.load(open(options.prior_report));open(prior,'w').write(json.dumps({'runId':r['id'],'base':r['base'],'findings':r['agent']['findings'],'outcome':r['outcome']},indent=2))
history=write('history.json',assignment('research','Investigate this architectural question: what does the report-tests operation prove about reporting, and what requires independent host acceptance? Use the explicitly supplied prior finding as evidence to evaluate, inspect current report tests, invoke operations.run report-tests once, and explain remaining uncertainty. Do not edit files. Complete checklist items with evidence.', ['Identify the supplied prior finding and compare it with current source/tests.','Run declared report-tests and explain limits of that evidence and independent acceptance.'],priorEvidence=[dict(path=prior,sourceId=r['id'],revision=r['base'],reason='Re-evaluate limits of an earlier operation qualification')]))
def case(id,project,base,component,path,kind,**kw):return dict(id=id,project=project,base=base,component=component,assignment=path,expectedOutcome='ready_for_integration' if kind in ['change','repair'] else 'research_completed',acceptance=[dict(command=node,args=[check,'{report}',kind],artifacts=[check])],**kw)
treepath=str(pathlib.Path(options.tree).resolve());treebase=subprocess.check_output(['git','-C',treepath,'rev-parse','HEAD'],text=True).strip();httppath=str(pathlib.Path(options.http).resolve());httpbase=subprocess.check_output(['git','-C',httppath,'rev-parse','HEAD'],text=True).strip()
cases=[case('report-change',root,base,'report',normal,'change',issue='48'),case('report-corrective-repair',root,base,'report',repair,'repair',issue='48',maxAttempts=2,faultInjection='One-time external acceptance harness replaces the implemented Operations heading; unchanged check must fail then pass after Luna edits real code.'),case('treeseed-command',treepath,treebase,'artifact-diagnostics',tree,'tree',issue='874',bindings=str(pathlib.Path(options.bindings).resolve())),case('local-http',httppath,httpbase,'http',http,'http'),case('prior-evidence-research',root,base,'report',history,'history',issue='48')]
write('manifest.json',dict(schemaVersion=1,runner=str(pathlib.Path(options.runner).resolve()),codexPath=options.codex,cases=cases))
print(base)
